-- Add 40 new media interview questions focusing on the broader Rockmundo world.
-- Upsert-safe by exact normalised question text; preserves existing rows/effects.
WITH seed (category, media_types, question_text, a,b,c,d) AS (VALUES
('gear_craft', ARRAY['radio','tv','podcast','magazine']::text[], 'Does your main instrument feel like part of your identity?', 'I''ve played it so much that the sound feels personal.', 'It''s a tool I know deeply, but the songs matter more.', 'I can make one note on it and people know it''s me.', 'It''s practically a band member, except it never pays rent.'),
('gear_craft', ARRAY['podcast','magazine','newspaper']::text[], 'What would matter most in a custom-built guitar or bass?', 'The feel in my hands and the tone through an amp.', 'I''d balance the wood, pickups and build quality.', 'I''d ask for a shape nobody else would dare play.', 'First, it has to survive our tour van.'),
('gear_craft', ARRAY['tv','radio','podcast']::text[], 'Would you take an instrument you built yourself onto a huge stage?', 'Yes, hearing it in front of a crowd would be incredible.', 'I''d test it thoroughly before trusting it for a headline set.', 'I''d make the instrument the centrepiece of the show.', 'As long as I remembered to fit the strap buttons.'),
('gear_craft', ARRAY['podcast','magazine','radio']::text[], 'How much does a good instrument setup affect a performance?', 'When it feels right, I stop thinking about the mechanics.', 'Reliable tuning and comfortable action make a difference.', 'A great setup can make you play things you hadn''t imagined.', 'A badly set guitar can ruin an otherwise good encore.'),
('gear_craft', ARRAY['all']::text[], 'Do you stick with familiar gear when recording something new?', 'I start with what I know so I can focus on the song.', 'We try alternatives when a track needs a different texture.', 'Sometimes the wrong guitar is exactly what makes it interesting.', 'I change pedals until the producer starts bargaining.'),
('gear_craft', ARRAY['podcast','magazine','newspaper']::text[], 'Is vintage gear worth the hunt or mostly nostalgia?', 'Old instruments can have a character I really value.', 'Condition and sound matter more to me than age.', 'I''d rather play a modern instrument with a truly original voice.', 'I refuse to pay extra for someone else''s scratches.'),
('gear_craft', ARRAY['radio','podcast','magazine']::text[], 'What makes a guitar tone instantly recognisable?', 'The way a player shapes each note matters most.', 'It''s the combination of instrument, amp and touch.', 'I love tones with enough personality to divide opinion.', 'If it sounds like a swarm of bees, we''ve gone too far.'),
('gear_craft', ARRAY['podcast','magazine','newspaper']::text[], 'Would you spend more on skilled road crew or new instruments?', 'A reliable crew protects the whole performance.', 'We''d decide based on what actually improves the live show.', 'I''d choose the people who make every gig possible.', 'The crew can fix the instruments after I break them.'),
('media_persona', ARRAY['tv','radio','podcast','magazine','newspaper']::text[], 'Does your approach change between a radio and TV interview?', 'Radio lets me focus on the conversation and the music.', 'On TV I think more about keeping answers concise.', 'I''ll be the same person whether there''s a camera or not.', 'On radio nobody can see my nervous hands.'),
('media_persona', ARRAY['all']::text[], 'What should journalists ask musicians more often?', 'Ask about the difficult choices behind a song.', 'I''d enjoy more conversations about craft and collaboration.', 'Ask what the industry gets wrong instead of chasing gossip.', 'Ask whether we''ve found a decent meal on tour.'),
('media_persona', ARRAY['tv','radio','podcast','magazine']::text[], 'Do long-form podcasts reveal more than short broadcast interviews?', 'Long conversations give creative ideas room to breathe.', 'Both formats can work when the interviewer listens.', 'Ten thoughtful minutes can beat two hours of chatter.', 'A podcast gives me more time to wander off topic.'),
('media_persona', ARRAY['all']::text[], 'How do you handle an interview question that catches you off guard?', 'I take a moment and answer as clearly as I can.', 'It''s fine to say I don''t know or need to think.', 'Unexpected questions can lead to the most interesting answers.', 'I look thoughtful while my brain searches for an exit.'),
('media_persona', ARRAY['tv','radio','podcast','magazine']::text[], 'Should artists practise media interviews before major appearances?', 'Preparation helps musicians speak without feeling trapped.', 'Knowing the format is useful, but I avoid scripts.', 'I''d rather stumble honestly than recite a polished statement.', 'I practise not saying anything I''ll regret at breakfast.'),
('media_persona', ARRAY['magazine','newspaper','podcast','tv']::text[], 'Would you refuse a huge interview if the outlet only wanted scandal?', 'Yes, music deserves more than a manufactured feud.', 'I''d ask for clarity about the interview''s purpose first.', 'A big audience doesn''t justify letting someone twist our words.', 'If they ask about the bassist''s socks, I''m leaving.'),
('media_persona', ARRAY['magazine','newspaper','podcast']::text[], 'What''s the best response to a headline that distorts your words?', 'I''d publish the full context and request a correction.', 'We''d contact the outlet calmly before escalating it.', 'I''d call out deliberate misrepresentation in public.', 'I''d put the actual quote on a T-shirt.'),
('media_persona', ARRAY['podcast','magazine','newspaper','tv']::text[], 'Would you let a journalist join your band on tour for a week?', 'Yes, if they showed the real work behind a live show.', 'We''d agree boundaries so everyone remains comfortable.', 'Let them see the chaos instead of reading a press release.', 'Only if they carry some of the equipment.'),
('fan_community', ARRAY['radio','tv','podcast','magazine']::text[], 'How should a band thank the fans from its earliest club shows?', 'Remember their support and keep making time for them.', 'We can offer meaningful experiences without making promises we can''t keep.', 'Those first supporters deserve a place in the band''s story.', 'I''d let them choose the encore, within reason.'),
('fan_community', ARRAY['all']::text[], 'What makes a music fan community feel welcoming?', 'People should feel safe to love the music in their own way.', 'Good moderation and respect help everyone belong.', 'Nobody should have to pass a trivia test to be a real fan.', 'If you sing the wrong lyric, we''ll sing it with you.'),
('fan_community', ARRAY['radio','tv','podcast','internet']::text[], 'Would you let fans vote on your encore song?', 'Yes, giving the crowd a choice could be fantastic.', 'I''d offer a shortlist we could play well.', 'Let them pick the deepest cut and surprise everyone.', 'Only if the vote doesn''t include a twenty-minute drum solo.'),
('fan_community', ARRAY['podcast','magazine','newspaper']::text[], 'How much should a fan club influence a band''s decisions?', 'Their feedback helps us understand what people value.', 'We listen carefully but keep creative decisions in the band.', 'Fans can challenge us without becoming our management.', 'They''re allowed to choose merch colours, not my haircut.'),
('fan_community', ARRAY['radio','tv','podcast','magazine']::text[], 'What would you say to someone who can''t afford a ticket to your show?', 'Their support matters whether they can attend or not.', 'We should try to keep some shows accessible.', 'Nobody''s love of music should be judged by what they can spend.', 'Please don''t apologise; keep listening and stay safe.'),
('fan_community', ARRAY['internet','podcast','magazine']::text[], 'Would you share a rough song demo with loyal supporters before release?', 'Yes, hearing an early version can bring fans into the process.', 'We''d share selected clips without spoiling the final track.', 'Let them hear the raw, unfiltered sound before anyone else.', 'Only after I erase my terrible guide vocal.'),
('fan_community', ARRAY['internet','podcast','magazine']::text[], 'How would you handle fans arguing online about your band''s new sound?', 'I''d remind everyone it''s fine to disagree respectfully.', 'We''d encourage conversation without rewarding abuse.', 'Nobody owns the band just because they liked us first.', 'I''ll ask them to settle it with a friendly dance-off.'),
('fan_community', ARRAY['radio','tv','podcast']::text[], 'What''s one feeling you hope people carry home from your concerts?', 'I want them to feel connected to other people in the room.', 'I''d love them to leave inspired and full of energy.', 'I want them to feel like they witnessed something fearless.', 'And I hope they remember where they parked.'),
('dj_nightlife', ARRAY['radio','podcast','tv','internet']::text[], 'Could a DJ set belong inside a live rock performance?', 'Yes, blending electronic textures with guitars could be exciting.', 'It depends on whether it serves the songs and the crowd.', 'A live mix could turn our set into something unexpected.', 'Only if nobody mistakes the drummer for a drum machine.'),
('dj_nightlife', ARRAY['podcast','magazine','radio']::text[], 'What separates a brilliant DJ from someone playing a playlist?', 'Reading a room and shaping its energy over time.', 'Smooth transitions matter, but selection matters even more.', 'A great DJ takes a crowd somewhere it didn''t expect.', 'Knowing when not to press the airhorn button.'),
('dj_nightlife', ARRAY['radio','podcast','tv']::text[], 'Would you play a late nightclub set after an arena concert?', 'If we had the energy, it could be a special intimate night.', 'I''d plan it carefully so the team could rest and travel safely.', 'An after-hours set could be where the wildest music happens.', 'Ask me before the encore, not after.'),
('dj_nightlife', ARRAY['podcast','magazine','internet']::text[], 'Would you let a DJ radically remix one of your songs?', 'Yes, I''d love to hear a new interpretation.', 'I''d want the original emotion to survive the new arrangement.', 'Let them tear the track apart and build something strange.', 'I just ask they leave one recognisable chord.'),
('dj_nightlife', ARRAY['radio','podcast','magazine']::text[], 'How can a DJ tell when a dancefloor is losing energy?', 'Watch how the crowd moves and reacts to transitions.', 'A gradual change in tempo or mood can reset the room.', 'Sometimes you need a bold left turn to wake everyone up.', 'If the bar queue is longer than the dancefloor, there''s a clue.'),
('dj_nightlife', ARRAY['podcast','radio','tv']::text[], 'If invited to DJ a club night, how would you approach it?', 'I''d build a journey through songs I genuinely love.', 'I''d prepare options and react to the crowd in the moment.', 'I''d risk a few unexpected tracks to make the night memorable.', 'I''d practise finding the right deck before pressing anything.'),
('dj_nightlife', ARRAY['magazine','newspaper','podcast']::text[], 'Should nightclubs give emerging local DJs regular slots?', 'Absolutely, that''s how new scenes find their own sound.', 'Regular opportunities help talent grow and venues build loyalty.', 'A local unknown could be tomorrow''s headliner.', 'Give them a proper soundcheck and a fair fee too.'),
('dj_nightlife', ARRAY['podcast','radio','magazine']::text[], 'What should a DJ do when a crowd doesn''t respond to the set?', 'Listen to the room and adjust without panicking.', 'Build momentum with a more accessible track before experimenting.', 'Drop something unexpected and change the entire mood.', 'Maybe check whether the speakers are actually on.'),
('career_business', ARRAY['podcast','magazine','newspaper']::text[], 'What would make a sponsorship deal worth accepting?', 'A partnership we genuinely believe in and can explain to fans.', 'Fair terms and creative independence would come first.', 'I won''t trade our identity for an oversized logo.', 'If the sponsor can repair the tour bus, I''ll listen.'),
('career_business', ARRAY['radio','podcast','magazine']::text[], 'Are streaming totals enough to measure a band''s impact?', 'No, songs can change lives without enormous numbers.', 'I''d look at repeat listeners, gigs and fan engagement too.', 'A loyal live crowd means more than a fleeting viral spike.', 'A million accidental autoplay streams wouldn''t impress me.'),
('career_business', ARRAY['podcast','magazine','newspaper']::text[], 'When does a band need a professional tour manager?', 'When the schedule gets too complex to manage responsibly.', 'A good manager saves time and prevents costly mistakes.', 'I''d hire someone before the chaos starts costing us shows.', 'When nobody remembers which city we''re in.'),
('career_business', ARRAY['podcast','magazine','newspaper']::text[], 'Should a band spend more on marketing or improving its live show?', 'A better show gives new fans a reason to stay.', 'I''d balance promotion with rehearsals and production needs.', 'I''d rather be unforgettable on stage than everywhere in adverts.', 'We should probably fix the broken microphone first.'),
('career_business', ARRAY['podcast','magazine','newspaper']::text[], 'How do you make expensive purchases without draining the band''s funds?', 'We plan around what we genuinely need to perform well.', 'I''d compare the long-term value with upcoming bills.', 'Some investments are worth taking a calculated risk for.', 'My wish list has never been approved in full.'),
('career_business', ARRAY['podcast','magazine','newspaper']::text[], 'Would you rather start your own label or sign with an established one?', 'I''d love the freedom of owning our releases.', 'I''d compare support, rights and responsibilities carefully.', 'I''d build something independent instead of giving up control.', 'Can my label name be something ridiculous?'),
('career_business', ARRAY['podcast','magazine','newspaper']::text[], 'What''s the fairest way to divide income from live performances?', 'Everyone should understand the agreement before the show.', 'I''d account for band costs and actual contributions transparently.', 'Nobody should quietly take more because they''re the loudest.', 'The drummer gets extra for carrying that kit.'),
('career_business', ARRAY['podcast','magazine','radio']::text[], 'Would you choose a lucrative private gig or a chance to meet new fans?', 'Connecting with new listeners can build a lasting career.', 'I''d weigh the opportunity against the band''s financial needs.', 'I''d pick the show with the chance to change everything.', 'How lucrative, and are snacks included?')
)
INSERT INTO public.interview_questions
 (category,media_types,question_text,option_a_text,option_a_effects,option_b_text,option_b_effects,option_c_text,option_c_effects,option_d_text,option_d_effects)
SELECT s.category,s.media_types,s.question_text,
s.a, jsonb_build_object('fame_mult',1.03,'fan_mult',1.04,'cash_mult',1.00,'reputation',jsonb_build_object('authentic',2,'professional',1)),
s.b, jsonb_build_object('fame_mult',1.01,'fan_mult',1.02,'cash_mult',1.02,'reputation',jsonb_build_object('diplomatic',2,'professional',2)),
s.c, jsonb_build_object('fame_mult',1.05,'fan_mult',0.99,'cash_mult',0.99,'reputation',jsonb_build_object('bold',2,'rebellious',2)),
s.d, jsonb_build_object('fame_mult',1.02,'fan_mult',1.01,'cash_mult',1.00,'reputation',jsonb_build_object('unpredictable',2,'authentic',1))
FROM seed s
WHERE NOT EXISTS(SELECT 1 FROM public.interview_questions q WHERE lower(btrim(q.question_text))=lower(btrim(s.question_text)));